function filterFit(o,moonIll,sep){const f=rig().filter;let s=100;if(f==='broadband'&&o.signal!=='broadband')s-=12;if(f!=='broadband'&&['Galaxy','Reflection','Dark','Cluster'].includes(o.type))return 5;if(f==='siioiii'&&o.signal==='haoiii')s-=18;if(f==='haoiii'&&o.signal==='oiii')s-=5;if(moonIll>.55){if(f==='broadband')s-=Math.max(0,65-sep)*.9+moonIll*30;else s-=Math.max(0,35-sep)*.35}return clamp(s)}
function sqmFromBortle(b){const table=[[1,21.9],[2,21.65],[3,21.4],[4,20.85],[5,19.75],[6,18.55],[7,17.4],[8,16.5],[9,15.5]];b=clamp(b,1,9);const lo=Math.floor(b),hi=Math.ceil(b);if(lo===hi)return table[lo-1][1];return table[lo-1][1]+(table[hi-1][1]-table[lo-1][1])*(b-lo)}
function lightPollutionFit(o){const p=place(),sqm=p.sqm||(+p.bortle?sqmFromBortle(+p.bortle):null);if(!sqm)return 82;const loss=clamp((21.8-sqm)/6.3,0,1),f=rig().filter;let penalty=loss*(f==='broadband'?55:f==='haoiii'?18:f==='siioiii'?14:10);if(['Galaxy','Reflection','Dark'].includes(o.type)&&f==='broadband')penalty+=loss*18;return clamp(Math.round(100-penalty))}
